extern int rd_stop_on;
int rd_jump_stop(uint32_t t, uint32_t at);
void rr_jump(uint32_t t, uint32_t at)
{
  if (rd_stop_on && rd_jump_stop(t, at)) return;   /* src/rd: a checked function jumping out */
  int lo = 0, hi = (int)(sizeof rr_ia_ / sizeof rr_ia_[0]) - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    if (t < rr_ia_[mid]) hi = mid - 1;
    else if (t > rr_ia_[mid]) lo = mid + 1;
    else { rr_fnp_[rr_if_[mid]](t); return; }
  }
  rr_trap(at, t, "jump to an address that is no known instruction");
}
/* an indirect CALL (jsr (An) / jsr through a table): the same dispatch as
 * rr_jump, but never a checked function "jumping out" -- the callee returns */
void rr_call_ind(uint32_t t, uint32_t at)
{
  int s = rd_stop_on; rd_stop_on = 0;
  rr_jump(t, at);
  rd_stop_on = s;
}
/* src/rd/rd_core.c: the lifted function that owns entry ep, to run it directly */
void (*rd_lifted_entry(uint32_t ep))(uint32_t)
{
  int lo = 0, hi = (int)(sizeof rr_ia_ / sizeof rr_ia_[0]) - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    if (ep < rr_ia_[mid]) hi = mid - 1;
    else if (ep > rr_ia_[mid]) lo = mid + 1;
    else return rr_fnp_[rr_if_[mid]];
  }
  return 0;
}
